         * The operation, for outgoing work.
         */operation: UInt64?, 
        /**
         * The peer.
         */peer: PeerInfo, 
        /**
         * Six digits.
         */code: String
    )
    /**
     * An offer was sent.
     */
    case offerSent(
        /**
         * The operation.
         */operation: UInt64, 
        /**
         * Transfer id.
         */transferId: String, 
        /**
         * The receiver.
         */peer: PeerInfo, 
        /**
         * Number of files.
         */files: UInt32, 
        /**
         * Total size.
         */totalBytes: UInt64
    )
    /**
     * An offer arrived (a `PromptOpened` follows when the user must answer).
     */
    case offerReceived(
        /**
         * Transfer id.
         */transferId: String, 
        /**
         * The sender.
         */peer: PeerInfo, 
        /**
         * Number of files.
         */files: UInt32, 
        /**
         * Total size.
         */totalBytes: UInt64
    )
    /**
     * The user must answer.
     */
    case promptOpened(
        /**
         * The question.
         */prompt: Prompt
    )
    /**
     * A prompt went away; later answers are refused.
     */
    case promptClosed(
        /**
         * Prompt id.
         */id: UInt64, 
        /**
         * Why.
         */reason: PromptCloseReason
    )
    /**
     * The receiver accepted.
     */
    case transferAccepted(
        /**
         * The operation, for outgoing work.
         */operation: UInt64?, 
        /**
         * Transfer id.
         */transferId: String
    )
    /**
     * Progress (at most ten per second per transfer).
     */
    case transferProgress(
        /**
         * The operation, for outgoing work.
         */operation: UInt64?, 
        /**
         * Transfer id.
         */transferId: String, 
        /**
         * Progress.
         */progress: Progress
    )
    /**
     * The receiver reported a file's result to this sender.
     */
    case fileSent(
        /**
         * The operation.
         */operation: UInt64, 
        /**
         * Transfer id.
         */transferId: String, 
        /**
         * File index.
         */index: UInt32, 
        /**
         * Result.
         */status: FileStatus
    )
    /**
     * A received file is stored and checked.
     */
    case fileSaved(
        /**
         * Transfer id.
         */transferId: String, 
        /**
         * File index.
         */index: UInt32, 
        /**
         * Final file name in the receive directory (never a path).
         */savedAs: String, 
        /**
         * Size.
         */size: UInt64, 
        /**
         * BLAKE3 digest (hex).
         */blake3: String
    )
    /**
     * A received file was not stored.
     */
    case fileFailed(
        /**
         * Transfer id.
         */transferId: String, 
        /**
         * File index.
         */index: UInt32, 
        /**
         * Result.
         */status: FileStatus
    )
    /**
     * A transfer ended.
     */
    case transferFinished(
        /**
         * The operation, for outgoing work.
         */operation: UInt64?, 
        /**
         * Direction.
         */direction: Direction, 
        /**
         * The result.
         */result: TransferResult
    )
    /**
     * A pairing window is open on this port.
     */
    case pairingWindowOpened(
        /**
         * The operation.
         */operation: UInt64, 
        /**
         * Port.
         */port: UInt16
    )
    /**
     * Pairing ended.
     */
    case pairingFinished(
        /**
         * The operation.
         */operation: UInt64, 
        /**
         * The result.
         */result: PairingResult
    )
    /**
     * A session ended without a transfer (denied, failed handshake, …).
     */
    case sessionClosed(
        /**
         * The peer, if it was authenticated.
         */peer: PeerInfo?, 
        /**
         * Error code or "normal".
         */code: String
    )
    /**
     * A problem that did not stop anything (local display only).
     */
    case warning(
        /**
         * Message.
         */message: String
    )
    /**
     * Less important events were dropped because the app fell behind.
     */
    case eventsDropped(
        /**
         * How many.
         */count: UInt64
    )
    /**
     * The app fell far behind: reload everything with `snapshot()`.
     */
    case resyncRequired





}

