 */

public enum Prompt: Equatable, Hashable {
    
    /**
     * Someone offers files.
     */
    case offer(
        /**
         * Answer with `answer_offer(id, …)`.
         */id: UInt64, 
        /**
         * Transfer id.
         */transferId: String, 
        /**
         * The sender.
         */peer: PeerInfo, 
        /**
         * Code to compare, for senders that are not paired.
         */code: String?, 
        /**
         * The first files (at most 200; see `offer_files`).
         */files: [OfferedFile], 
        /**
         * Number of files.
         */fileCount: UInt32, 
        /**
         * Total size.
         */totalBytes: UInt64, 
        /**
         * When the request expires (Unix milliseconds).
         */expiresAtMs: UInt64
    )
    /**
     * Both screens must show the same code.
     */
    case code(
        /**
         * Answer with `answer_sas(id, …)`.
         */id: UInt64, 
        /**
         * The operation that asks, if any.
         */operation: UInt64?, 
        /**
         * The peer.
         */peer: PeerInfo, 
        /**
         * The six-digit code.
         */code: String, 
        /**
         * Why it is shown.
         */purpose: CodePurpose, 
        /**
         * When the request expires (Unix milliseconds).
         */expiresAtMs: UInt64
    )





}

